macro_rules! deps {
    () => {
        Context!();
        NopLayer!();
        Layer!();
        LookupSpan!();
    };
}

macro_rules! registry_tests {
    () => {
        deps!();
        # [cfg (all (feature = "registry" , feature = "std"))] mod registry_tests { use std :: dbg ; use super :: * ; use crate :: registry :: LookupSpan ; # [test] fn context_event_span () { use std :: sync :: { Arc , Mutex } ; let last_event_span = Arc :: new (Mutex :: new (None)) ; struct RecordingLayer { last_event_span : Arc < Mutex < Option < & 'static str > > > , } impl < S > Layer < S > for RecordingLayer where S : Subscriber + for < 'lookup > LookupSpan < 'lookup > , { fn on_event (& self , event : & Event < '_ > , ctx : Context < '_ , S >) { let span = ctx . event_span (event) ; * self . last_event_span . lock () . unwrap () = span . map (| s | s . name ()) ; } } tracing :: subscriber :: with_default (crate :: registry () . with (RecordingLayer { last_event_span : last_event_span . clone () , }) , | | { tracing :: info ! ("no span") ; assert_eq ! (* last_event_span . lock () . unwrap () , None) ; let parent = tracing :: info_span ! ("explicit") ; tracing :: info ! (parent : & parent , "explicit span") ; assert_eq ! (* last_event_span . lock () . unwrap () , Some ("explicit")) ; let _guard = tracing :: info_span ! ("contextual") . entered () ; tracing :: info ! ("contextual span") ; assert_eq ! (* last_event_span . lock () . unwrap () , Some ("contextual")) ; } ,) ; } # [doc = " Tests for how max-level hints are calculated when combining layers"] # [doc = " with and without per-layer filtering."] mod max_level_hints { use super :: * ; use crate :: filter :: * ; # [test] fn mixed_with_unfiltered () { let subscriber = crate :: registry () . with (NopLayer) . with (NopLayer . with_filter (LevelFilter :: INFO)) ; assert_eq ! (subscriber . max_level_hint () , None) ; } # [test] fn mixed_with_unfiltered_layered () { let subscriber = crate :: registry () . with (NopLayer) . with (NopLayer . with_filter (LevelFilter :: INFO) . and_then (NopLayer . with_filter (LevelFilter :: TRACE)) ,) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , None) ; } # [test] fn mixed_interleaved () { let subscriber = crate :: registry () . with (NopLayer) . with (NopLayer . with_filter (LevelFilter :: INFO)) . with (NopLayer) . with (NopLayer . with_filter (LevelFilter :: INFO)) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , None) ; } # [test] fn mixed_layered () { let subscriber = crate :: registry () . with (NopLayer . with_filter (LevelFilter :: INFO) . and_then (NopLayer)) . with (NopLayer . and_then (NopLayer . with_filter (LevelFilter :: INFO))) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , None) ; } # [test] fn plf_only_unhinted () { let subscriber = crate :: registry () . with (NopLayer . with_filter (LevelFilter :: INFO)) . with (NopLayer . with_filter (filter_fn (| _ | true))) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , None) ; } # [test] fn plf_only_unhinted_nested_outer () { let subscriber = crate :: registry () . with (NopLayer . with_filter (LevelFilter :: INFO) . and_then (NopLayer . with_filter (LevelFilter :: WARN)) ,) . with (NopLayer . with_filter (filter_fn (| _ | true)) . and_then (NopLayer . with_filter (LevelFilter :: DEBUG)) ,) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , None) ; } # [test] fn plf_only_unhinted_nested_inner () { let subscriber = dbg ! (crate :: registry () . with (NopLayer . with_filter (filter_fn (| _ | true)) . and_then (NopLayer . with_filter (filter_fn (| _ | true))) . with_filter (LevelFilter :: INFO) ,)) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , Some (LevelFilter :: INFO)) ; } # [test] fn unhinted_nested_inner () { let subscriber = dbg ! (crate :: registry () . with (NopLayer . and_then (NopLayer) . with_filter (LevelFilter :: INFO)) . with (NopLayer . with_filter (filter_fn (| _ | true)) . and_then (NopLayer . with_filter (filter_fn (| _ | true))) . with_filter (LevelFilter :: WARN) ,)) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , Some (LevelFilter :: INFO)) ; } # [test] fn unhinted_nested_inner_mixed () { let subscriber = dbg ! (crate :: registry () . with (NopLayer . and_then (NopLayer . with_filter (filter_fn (| _ | true))) . with_filter (LevelFilter :: INFO)) . with (NopLayer . with_filter (filter_fn (| _ | true)) . and_then (NopLayer . with_filter (filter_fn (| _ | true))) . with_filter (LevelFilter :: WARN) ,)) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , Some (LevelFilter :: INFO)) ; } # [test] fn plf_only_picks_max () { let subscriber = crate :: registry () . with (NopLayer . with_filter (LevelFilter :: WARN)) . with (NopLayer . with_filter (LevelFilter :: DEBUG)) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , Some (LevelFilter :: DEBUG)) ; } # [test] fn many_plf_only_picks_max () { let subscriber = crate :: registry () . with (NopLayer . with_filter (LevelFilter :: WARN)) . with (NopLayer . with_filter (LevelFilter :: DEBUG)) . with (NopLayer . with_filter (LevelFilter :: INFO)) . with (NopLayer . with_filter (LevelFilter :: ERROR)) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , Some (LevelFilter :: DEBUG)) ; } # [test] fn nested_plf_only_picks_max () { let subscriber = crate :: registry () . with (NopLayer . with_filter (LevelFilter :: INFO) . and_then (NopLayer . with_filter (LevelFilter :: WARN) . and_then (NopLayer . with_filter (LevelFilter :: DEBUG)) ,) ,) . with (NopLayer . with_filter (LevelFilter :: INFO) . and_then (NopLayer . with_filter (LevelFilter :: ERROR)) ,) ; assert_eq ! (dbg ! (subscriber) . max_level_hint () , Some (LevelFilter :: DEBUG)) ; } } }
    };
}

registry_tests!()